        # y2 can be derived from x1 and y1, since both paths have the same number of steps
        y2 = x1 + y1 - x2
        if y2 < 0 or y2 >= N:
            return -float('inf')
        if x1 == N - 1 and y1 == N - 1:
            return grid.get((x1, y1), 0)
        if dp[x1][y1][x2] != -1:
            return dp[x1][y1][x2]

        collect = grid.get((x1, y1), 0)
        if x1 != x2:
            collect += grid.get((x2, y2), 0)

        max_val = max([
            dfs(x1 + 1, y1, x2 + 1),
            dfs(x1 + 1, y1, x2),
            dfs(x1, y1 + 1, x2 + 1),
            dfs(x1, y1 + 1, x2)
        ])

        dp[x1][y1][x2] = collect + max_val
        return dp[x1][y1][x2]

    return dfs(0, 0, 0)

