def cantor_numbering(N: int) -> str:
    '''
    Determine the numerator and denominator of the N-th term in the Cantor table.

    Args:
    - N (int): The position in the Cantor table to find the corresponding fraction for.

    Returns:
    - str: A string representation of the fraction at the N-th position in the Cantor table.
    '''
    if N <= 0:
        return "Invalid input: N must be a positive integer"

    row = 1
    column = 1
    total = 1

    while total < N:
        if row % 2 == 1:
            column += 1
        else:
            row += 1
        total += row + column - 2

    if N == total:
        return f"{row - column + 1}/{column}"
    elif N == total - 1:
        return f"{column}/{row - column + 1}"
    else:
        if row % 2 == 1:
            return f"{total - N + 1}/{N - (total - row)}"
        else:
            return f"{N - (total - column)}/{total - N + 1}"

def max_product(num_str: str, N: int, K: int) -> int:
    """Calculate the maximum product by inserting K multiplication signs into the number string."""

    if N - 1 == K:
        return int(num_str)
    if K == 0:
        return int(num_str)

    max_product = 0
    for i in range(1, N - K):
        left_part = num_str[:i]
        right_part = num_str[i:]
        current_product = int(left_part) * int(right_part)
        remaining_product = max_product(right_part[K-i+1:], K-i-1) if K-i-1 >= 0 else 1
        max_product = max(max_product, current_product * remaining_product)

    return max_product

def max_product(num_str: str, N: int, K: int) -> int:
    """Find the maximum product of a number string by inserting K multiplication signs."""
    def max_recursive(num_str, N, K, current_product, last_index):
        if K == 0:
            return int(num_str[last_index:])

        max_product = 0
        for i in range(last_index + 1, N):
            new_product = current_product * int(num_str[last_index:i])
            max_product = max(max_product, new_product, max_recursive(num_str, N, K - 1, new_product, i))

        return max_product

    return max_recursive(num_str, N, K, int(num_str[:1]), 0)

