            if col_aisles[0] <= pair[1] < col_aisles[1] <= pair[3] or col_aisles[0] <= pair[3] < col_aisles[1] <= pair[1]:
                separated_pairs += 1
        return separated_pairs

    max_horizontal_separations = 0
    max_vertical_separations = 0
    best_row_aisles = (-1, -1)
    best_col_aisles = (-1, -1)

    for i in range(1, M):
        row_aisles = (i, i + 1)
        horizontal_separations = calculate_separation(row_aisles, None)
        if horizontal_separations > max_horizontal_separations:
            max_horizontal_separations = horizontal_separations
            best_row_aisles = row_aisles

    for j in range(1, N):
        col_aisles = (j, j + 1)
        vertical_separations = calculate_separation(None, col_aisles)
        if vertical_separations > max_vertical_separations:
            max_vertical_separations = vertical_separations
            best_col_aisles = col_aisles

    if best_row_aisles[0] < 1 or best_row_aisles[1] > M:
