def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    row_count = [0] * (M + 1)
    col_count = [0] * (N + 1)

    for pair in chatting_pairs:
        xi, yi, pi, qi = pair[0] - 1, pair[1] - 1, pair[2] - 1, pair[3] - 1
        if xi == pi:  # Same row
            if yi < qi:
                row_count[yi] += 1
                row_count[qi + 1] -= 1
            else:
                row_count[qi] += 1
                row_count[yi + 1] -= 1
        else:  # Same column
            if yi < qi:
                col_count[yi] += 1
                col_count[qi + 1] -= 1
            else:
                col_count[qi] += 1
                col_count[yi + 1] -= 1

    for i in range(1, M):
        row_count[i] += row_count[i - 1]

    for i in range(1, N):
        col_count[i] += col_count[i - 1]

    row_sep = []
    col_sep = []

    for i in range(1, M + 1):
        if row_count[i] > 0:
            row_sep.append(i)

    for i in range(1, N + 1):
        if col_count[i] > 0:
            col_sep.append(i)

    row_sep = row_sep[:K]
    col_sep = col_sep[:L]

    return ' '.join(map(str, row_sep)), ' '.join(map(str, col_sep))

def count_passing_ways(n: int, m: int) -> int:
    MOD = 998244353

    if n == 1:
        return 1 if m == 0 else 0

    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1

    for passes in range(1, m + 1):
        dp[0][passes % n] = dp[(n - 1) % n][passes - 1] + dp[(1) % n][passes - 1]
        dp[0][passes % n] %= MOD

        for i in range(1, n):
            dp[i][passes % n] = dp[(i - 1) % n][passes - 1] + dp[(i + 1) % n][passes - 1]
            dp[i][passes % n] %= MOD

    return dp[0][m % n]

def count_passing_ways(n: int, m: int) -> int:
    MOD = 10**9 + 7

    # Initialize the DP table
    dp = [[0] * (m + 1) for _ in range(n)]

    # Base cases: There's one way to be at the starting point with 0 passes
    for i in range(n):
        dp[i][0] = 1

    # Fill the DP table
    for k in range(1, m + 1):
        for i in range(n):
            dp[i][k] = (dp[(i - 1) % n][k - 1] + dp[(i + 1) % n][k - 1]) % MOD

    # The result is the number of ways to be at the starting point with m passes
    return dp[0][m]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a list to store the maximum importance value for each budget
    dp = [0] * (n + 1)

    # Iterate over each item
    for price, importance in items:
        # Update the dp array from the back to avoid using the same item multiple times
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + importance)

    # The maximum importance value will be in the last element of dp array
    return dp[n]

