def generate_numbers(n, rules) -> int:
    from collections import deque

    # Convert the initial number to a string for easier manipulation
    n_str = str(n)
    # Initialize the BFS queue with the initial number
    queue = deque([n_str])
    # Use a set to keep track of unique numbers generated
    unique_numbers = set([n_str])

    while queue:
        current = queue.popleft()
        for i in range(len(current)):
            for x, y in rules:
                if current[i] == str(x):
                    # Apply the transformation rule
                    new_number = current[:i] + str(y) + current[i+1:]
                    # If the new number is not already in the set, add it to the queue and set
                    if new_number not in unique_numbers:
                        queue.append(new_number)
                        unique_numbers.add(new_number)

    # Return the count of unique numbers
    return len(unique_numbers)

