    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(min(j, a[i - 1]) + 1):
                dp[i][j] += dp[i - 1][j - k]
                dp[i][j] %= MOD

    return dp[n][m]

def calculate_arrangements(n, m, a) -> int:
    dp = [1] + [0] * m

    for i in range(n):
        for j in range(m, a[i] - 1, -1):
            dp[j] = (dp[j] + dp[j - a[i]]) % MOD

    return dp[m]

