def calculate_arrangements(n: int, m: int, a: List[int]) -> int:
    # Initialize DP table with zeros
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There's one way to arrange 0 pots with 0 types
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= 1:
                dp[i][j] += dp[i][j - 1]
                if j <= a[i - 1]:
                    dp[i][j] += dp[i - 1][j - a[i - 1]]
                dp[i][j] %= MOD

    return dp[n][m]

