    :param heights: A list of student heights.
    :type heights: List[int]
    :return: The minimum number of students that need to leave.
    :rtype: int
    """
    n = len(heights)
    if n <= 1:
        return 0

    # Calculate the longest increasing subsequence (LIS) ending at each position
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Calculate the longest decreasing subsequence (LDS) starting at each position
    lds = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Find the maximum value of (LIS[i] + LDS[i]) - 1 for all i
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, lis[i] + lds[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum choir length
    return n - max_choir_length

