    if n == 0:
        return 0

    max_height_left = [0] * n
    max_height_right = [0] * n

    max_height_left[0] = heights[0]
    for i in range(1, n):
        max_height_left[i] = max(max_height_left[i - 1], heights[i])

    max_height_right[n - 1] = heights[n - 1]
    for i in range(n - 2, -1, -1):
        max_height_right[i] = max(max_height_right[i + 1], heights[i])

    min_students_to_leave = n
    for i in range(0, n):
        if i == 0:
            min_students_to_leave = min(min_students_to_leave, n - 1 - (max_height_right[1] - heights[i]))
        elif i == n - 1:
            min_students_to_leave = min(min_students_to_leave, i - (max_height_left[n - 2] - heights[i]))
        else:
            min_students_to_leave = min(min_students_to_leave, i - (max_height_left[i - 1] - heights[i]) + (n - 1 - i - (max_height_right[i + 1] - heights[i])))

    return min_students_to_leave

def hanoi_double_iterative(n: int) -> int:
    if n < 0:
        raise ValueError("The number of disc pairs must be a non-negative integer.")
    moves = 0
    for i in range(1, n + 1):
        moves += 2 ** i - 1
    return moves
